prompt --application/shared_components/navigation/lists/projects_menu
begin
wwv_flow_imp_shared.create_list(
 p_id=>wwv_flow_imp.id(11404336960845895721)
,p_name=>'Projects menu'
,p_static_id=>'projects-menu'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- 1. Top Item: Opens Page 3 as a Modal Dialog',
'SELECT ',
'    1                                                      AS lvl, ',
'    ''Add New Project''                                      AS label, ',
'    -- Safely generates the secure URL required to trigger an APEX modal dialog',
'    APEX_PAGE.GET_URL(p_page => 3)                         AS target, ',
'    ''NO''                                                   AS is_current, ',
'    ''fa-plus-circle''                                       AS image, ',
'    null                                                   AS image_attr, ',
'    null                                                   AS image_alt,',
'    null                                                   AS attr1,',
'    null                                                   AS attr2,',
'    null                                                   AS attr3',
'FROM DUAL',
'',
'UNION ALL',
'',
'-- 2. Project Items: Refresh current page with selected PROJECT_ID',
'SELECT ',
'    1                                                      AS lvl, ',
'    PROJECT_NAME                                           AS label, ',
'    -- Targets current page and sets the global session variable',
'    ''f?p=''||:APP_ID||'':''||:APP_PAGE_ID||'':''||:APP_SESSION||''::NO::GLOBAL_PROJECT_ID:''||PROJECT_ID AS target, ',
'    ''NO''                                                   AS is_current, ',
'    ''fa-briefcase''                                         AS image, ',
'    null                                                   AS image_attr, ',
'    null                                                   AS image_alt,',
'    null                                                   AS attr1,',
'    null                                                   AS attr2,',
'    null                                                   AS attr3',
'FROM PROJECTS',
'ORDER BY lvl ASC, label ASC; -- Ensures the ''Add New'' item stays strictly on top'))
,p_version_scn=>'SH256:PtUQQ75oIhZjBZyLUloIONVqrC7jrTFxFWe5PK426FM'
,p_created_on=>wwv_flow_imp.dz('20261105163712Z')
,p_updated_on=>wwv_flow_imp.dz('20261105165942Z')
,p_created_by=>'GUILHERMERDARU@GMAIL.COM'
,p_updated_by=>'GUILHERMERDARU@GMAIL.COM'
);
