'apex.jQuery(document).on(',
'    "click",',
'    "#BTN_TOGGLE_MENU",',
'    function (event) {',
'        event.preventDefault();',
'        apex.jQuery("body").toggleClass("sidebar-visible");',
'    }',
');',
'//drag and drop',
'window.initKanbanSortable = function() {',
'    // Destroy existing sortable instance first to prevent duplication bugs',
'    if ($(".kanban-cards-container").hasClass("ui-sortable")) {',
'        $(".kanban-cards-container").sortable("destroy");',
'    }',
'',
'    $(".kanban-cards-container").sortable({',
'        connectWith: ".kanban-cards-container",',
'        placeholder: "ui-sortable-placeholder",',
'        receive: function(event, ui) {',
'            var taskId = ui.item.data("task-id");',
'            var newStatusId = $(this).closest(".kanban-column").data("status-id");',
'',
'            apex.server.process(',
'                "UPDATE_TASK_STATUS",',
'                {',
'                    x01: taskId,',
'                    x02: newStatusId',
'                },',
'                {',
'                    dataType: "json",',
'                    success: function(data) {',
'                        if (!data.success) {',
'                            apex.message.error("Failed to update status: " + data.message);',
'                            $(ui.sender).sortable("cancel");',
'                        }',
'                    },',
'                    error: function() {',
'                        apex.message.error("Server connection failed.");',
'                        $(ui.sender).sortable("cancel");',
'                    }',
'                }',
'            );',
'        }',
'    }).disableSelection();',
'};',
'',
'// Prevent drag triggers when interacting with input elements',
'$(document).on("mousedown touchstart", ".kanban-card input, .kanban-card button", function(e) {',
'    e.stopPropagation();',
'});',
'',
'// Initial run on page load',
'$(function() {',
'    initKanbanSortable();',
'});',
'',
'',
'window.initKanbanSortable = function() {',
'    // Clean up existing instance to prevent duplication',
'    if ($(".kanban-cards-container").hasClass("ui-sortable")) {',
'        $(".kanban-cards-container").sortable("destroy");',
'    }',
'',
'    $(".kanban-cards-container").sortable({',
'        connectWith: ".kanban-cards-container",',
'        placeholder: "ui-sortable-placeholder",',
'        receive: function(event, ui) {',
'            var taskId = ui.item.data("task-id");',
'            var newStatusId = $(this).closest(".kanban-column").data("status-id");',
'',
'            apex.server.process(',
'                "UPDATE_TASK_STATUS",',
'                {',
'                    x01: taskId,',
'                    x02: newStatusId',
'                },',
'                {',
'                    dataType: "json",',
'                    success: function(data) {',
'                        if (!data.success) {',
'                            apex.message.error("Failed to update status: " + data.message);',
'                            $(ui.sender).sortable("cancel");',
'                        }',
'                    },',
'                    error: function() {',
'                        apex.message.error("Server connection failed.");',
'                        $(ui.sender).sortable("cancel");',
'                    }',
'                }',
'            );',
'        }',
'    }).disableSelection();',
'};',
'',
'// Prevent drag triggers when clicking input fields/buttons',
'$(document).on("mousedown touchstart", ".kanban-card input, .kanban-card button", function(e) {',
'    e.stopPropagation();',
'});',
'',
'// 3. Add Comment Function',
'window.addComment = function(taskId, btnElement) {',
'    var $card = $(btnElement).closest(".kanban-card");',
'    var $input = $card.find(".new-comment-input");',
'    var commentText = $input.val().trim();',
'',
'    if (!commentText) {',
'        return;',
'    }',
'',
'    apex.server.process(',
'        "ADD_TASK_COMMENT",',
'        {',
'            x01: taskId,',
'            x02: commentText',
'        },',
'        {',
'            dataType: "json",',
'            success: function(data) {',
'                if (data.success) {',
'                    // Refresh the Kanban region so the new comment appears instantly',
'                    apex.region("taks-content").refresh();',
'                } else {',
'                    apex.message.alert("Failed to add comment: " + data.message);',
'                }',
'            },',
'            error: function() {',
'                apex.message.alert("Server connection failed.");',
'            }',
'        }',
'    );',
'};',
'',
'// 1. Initialize on initial page load',
'$(function() {',
'    initKanbanSortable();',
'});',
'',
'// 2. Automatically re-initialize whenever the region with Static ID ''taks-content'' is refreshed',
'$(''#taks-content'').on(''apexafterrefresh'', function() {',
'    initKanbanSortable();',
'}',
'',
'',
');'))
