wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(9538741240116413839)
,p_plug_name=>'TAKS_CONTENT'
,p_static_id=>'taks-content'
,p_title=>'Tasks'
,p_region_name=>'taks-content'
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody'
,p_plug_template=>4075786578761660127
,p_plug_display_sequence=>60
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'	DECLARE',
'	    v_clob CLOB;',
'	    v_project_name VARCHAR2(1000);',
'	    ',
'	    -- Helper procedure to append HTML strings to the CLOB',
'	    PROCEDURE p(p_str IN VARCHAR2) IS',
'	    BEGIN',
'	        DBMS_LOB.WRITEAPPEND(v_clob, LENGTH(p_str), p_str);',
'	    END;',
'	BEGIN',
'	    -- Initialize the temporary CLOB',
'	    DBMS_LOB.CREATETEMPORARY(v_clob, TRUE);',
'	    IF(:GLOBAL_PROJECT_ID IS NOT NULL) THEN',
'	    SELECT PROJECT_NAME INTO v_project_name FROM PROJECTS WHERE PROJECT_ID = :GLOBAL_PROJECT_ID;',
'		    	p(''      <div class="kanban-card-pj-name">'' ||',
'		    			v_project_name',
'		    	 || ''</div>'');',
'		END IF;',
'	    p(''<div class="kanban-board">'');',
'',
'	    -- Iterate through each status column',
'	    FOR col IN (',
'	        SELECT status_id, status_desc ',
'	          FROM status ',
'	         ORDER BY status_id',
'	    ) LOOP',
'	        p(''<div class="kanban-column" data-status-id="'' || col.status_id || ''">'');',
'	        p(''  <div class="kanban-column-header">'');',
'	        p(''    <h3>'' || APEX_ESCAPE.html(col.status_desc) || ''</h3>'');',
'	        p(''  </div>'');',
'	        p(''  <div class="kanban-cards-container" id="status-col-'' || col.status_id || ''">'');',
'',
'	        -- Iterate through tasks belonging to this status column',
'	        FOR c IN (',
'	            SELECT task_id, task_name, task_desc ,',
'	            TO_CHAR(TASK_BEGIN_DATE,''DD/MM/RRRR'') BGN_DT,',
'	            TO_CHAR(TASK_END_DATE,''DD/MM/RRRR'') END_DT,',
'	            p.PROJECT_NAME',
'	              FROM tasks  t',
'	                LEFT JOIN PROJECTS p ON (p.PROJECT_ID = t.PROJECT_ID)',
'	             WHERE status_id = col.status_id ',
'	             AND t.project_id = :GLOBAL_PROJECT_ID',
'	             ORDER BY task_id DESC',
'	        ) LOOP',
'	            p(''    <div class="kanban-card" data-task-id="'' || c.task_id || ''">'');',
'	            p(''      <div class="kanban-card-pj-name">'' || APEX_ESCAPE.html(c.PROJECT_NAME) || ''</div>'');',
'	            p(''      <div class="kanban-card-title">'' || APEX_ESCAPE.html(c.task_name) || ''</div>'');',
'	            p(''      <div class="kanban-card-desc">'' || APEX_ESCAPE.html(c.task_desc) || ''</div>'');',
'	            p(''      <div class="kanban-card-dt">Begin Date: '' || APEX_ESCAPE.html(c.BGN_DT) || ''</div>'');',
'	            p(''      <div class="kanban-card-dt">END Date: '' || APEX_ESCAPE.html(c.end_DT) || ''</div>'');',
'	            ',
'	            -- Existing Comments Section',
'	            p(''      <div class="kanban-card-comments" id="comments-task-'' || c.task_id || ''">'');',
'	            FOR comm IN (',
'	                SELECT comment_text, created_at ',
'	                  FROM task_comments ',
'	                 WHERE task_id = c.task_id ',
'	                 ORDER BY created_at ASC',
'	            ) LOOP',
'	                p(''        <div class="comment-item">'');',
'	                p(''          <small>'' || TO_CHAR(comm.created_at, ''DD/MM/RRRR'') || ''</small>'');',
'	                p(''          <p>'' || APEX_ESCAPE.html(comm.comment_text) || ''</p>'');',
'	                p(''        </div>'');',
'	            END LOOP;',
'	            p(''      </div>'');',
'',
'	            -- New Comment Input Field & Button',
'	            p(''      <div class="kanban-card-add-comment">'');',
'	            p(''        <input type="text" class="new-comment-input" placeholder="Add a comment..." />'');',
'	            p(''        <button type="button" class="t-Button t-Button--tiny t-Button--hot btn-add-comment" onclick="addComment('' || c.task_id || '', this)">Post</button>'');',
'	            p(''      </div>'');',
'',
'	            p(''    </div>''); -- End Card',
'	        END LOOP;',
'',
'	        p(''  </div>''); -- End Cards Container',
'	        p(''</div>''); -- End Column',
'	    END LOOP;',
'',
'	    p(''</div>''); -- End Board',
'',
'	    -- Return the generated HTML content to APEX',
'	    RETURN v_clob;',
'	END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_created_on=>wwv_flow_imp.dz('20261105150826Z')
,p_updated_on=>wwv_flow_imp.dz('20261105165513Z')
,p_created_by=>'GUILHERMERDARU@GMAIL.COM'
,p_updated_by=>'GUILHERMERDARU@GMAIL.COM'
);
