,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'ADD_TASK_COMMENT'
,p_static_id=>'add-task-comment'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_task_id      NUMBER        := apex_application.g_x01;',
'    v_comment_text VARCHAR2(4000) := apex_application.g_x02;',
'BEGIN',
'    INSERT INTO task_comments (task_id, comment_text, created_at)',
'    VALUES (v_task_id, v_comment_text, SYSDATE);',
'',
'    apex_json.open_object;',
'    apex_json.write(''success'', true);',
'    apex_json.write(''formatted_date'', TO_CHAR(SYSDATE, ''YYYY-MM-DD HH24:MI''));',
'    apex_json.close_object;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.open_object;',
'        apex_json.write(''success'', false);',
'        apex_json.write(''message'', SQLERRM);',
'        apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>9538741413983413841
,p_created_on=>wwv_flow_imp.dz('20261105150826Z')
